create table public.tax_jurisdictions (id uuid primary key default gen_random_uuid(), country_code char(2) not null, jurisdiction_code text not null, name text not null, parent_jurisdiction_id uuid references public.tax_jurisdictions(id), timezone text, currency char(3), active boolean not null default true, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(country_code,jurisdiction_code));
create table public.tax_categories (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, description text, active boolean not null default true, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tax_rates (id uuid primary key default gen_random_uuid(), jurisdiction_id uuid not null references public.tax_jurisdictions(id), tax_category_id uuid not null references public.tax_categories(id), rate numeric(12,8) not null check(rate>=0), effective_from timestamptz not null, effective_to timestamptz, source_reference text, active boolean not null default true, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(effective_to is null or effective_to>effective_from));
create table public.tax_rules (id uuid primary key default gen_random_uuid(), jurisdiction_id uuid not null references public.tax_jurisdictions(id), tax_category_id uuid not null references public.tax_categories(id), rule_code text not null, taxpayer_role text not null check(taxpayer_role in('platform','seller','buyer','affiliate','provider','other')), collection_role text not null check(collection_role in('platform','seller','third_party','none')), calculation_method text not null check(calculation_method in('percentage','fixed','exempt','not_applicable')), rate_id uuid references public.tax_rates(id), priority integer not null default 100 check(priority>=0), effective_from timestamptz not null, effective_to timestamptz, active boolean not null default true, conditions jsonb not null default '{}'::jsonb, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(jurisdiction_id,rule_code), check(effective_to is null or effective_to>effective_from));
